model Node {
  id            String     @id @default(cuid())
  name          String     @unique
  pveNode       String // Proxmox node name (e.g. ns5002569)
  apiUrl        String // https://host:8006
  tokenId       String
  tokenSecret   String
  publicIp      String
  bridge        String     @default("vmbr1")
  subnetPrefix  String     @default("10.20.0.") // /24 NAT subnet prefix
  ipStart       Int        @default(100)
  ipEnd         Int        @default(250)
  sshPortStart  Int        @default(20000)
  sshPortEnd    Int        @default(29999)
  natChain      String     @default("NXEON_FWD")
  storageNvme   String     @default("vmdata")
  storageHdd    String     @default("vmdata-hdd")
  capacityRamMB Int        @default(56000)
  isPrimary     Boolean    @default(false)
  enabled       Boolean    @default(true)
  status        NodeStatus @default(ONLINE)
  lastSeenAt    DateTime?
  createdAt     DateTime   @default(now())
  servers       Server[]
}

enum InvoiceStatus {
  OPEN
  PAID
  VOID
  REFUNDED
}

model Invoice {
  id            String        @id @default(cuid())
  number        Int           @unique @default(autoincrement())
  userId        String
  user          User          @relation(fields: [userId], references: [id], onDelete: Cascade)
  amountCents   Int
  taxCents      Int           @default(0)
  status        InvoiceStatus @default(OPEN)
  // How much of this invoice has already been refunded. Refunds used to be bound
  // to nothing: `refundPayment` took only (userId, amount) and picked its Stripe
  // target as "most recent top-up, any amount" — so refunding a $24 March invoice
  // issued $24 against the customer's $200 July top-up, the invoice stayed PAID,
  // and the next admin refunded it again. Tracking it here lets the action refuse
  // to exceed the original and mark the invoice REFUNDED.
  refundedCents Int           @default(0)
  description   String
  lineItems     Json // [{ description, qty, unitCents, amountCents }]
  periodStart   DateTime?
  periodEnd     DateTime?
  paidAt        DateTime?
  // Snapshot of the card used to pay this invoice, captured at the PAID transition
  // so the record survives the customer later swapping or removing their card.
  // Nullable + additive: invoices issued before this existed fall back to the
  // user's current card fields at render time.
  paidBrand     String? // card brand snapshot at time paid (e.g. "visa")
  paidLast4     String? // card last4 snapshot at time paid
  createdAt     DateTime      @default(now())
}

// ---- Growth: coupons / promo codes ----
enum CouponKind {
  PERCENT // value = percent 1-100 (discount on order/topup)
  FIXED_CENTS // value = cents off
  CREDIT_CENTS // value = cents of wallet credit granted on redemption
}

enum CouponScope {
  ANY
  TOPUP
  ORDER
}

/// Which product family a coupon may be redeemed against at checkout.
enum CouponServiceKind {
  ANY
  VPS
  GAME
}

model Coupon {
  id             String             @id @default(cuid())
  code           String             @unique
  kind           CouponKind
  value          Int
  scope          CouponScope        @default(ANY)
  // Which product family this coupon may be used on at checkout. ANY = no
  // restriction; VPS / GAME limit it to that kind of order.
  serviceKind    CouponServiceKind  @default(ANY)
  // Restrict to ONE specific plan by slug (e.g. "starter"). Null = any plan
  // within `serviceKind`. This is how "one free month on the Starter VPS" is
  // locked to Starter and cannot be spent on a bigger plan.
  planSlug       String?
  // Cap how many months of the term the coupon may discount. 1 = one month only,
  // so a percentage/free coupon cannot be stretched across a 12-month order to
  // give a year free. Null = the whole term.
  maxTermMonths  Int?
  firstTimeOnly  Boolean            @default(false)
  minAmountCents Int?
  maxRedemptions Int?
  timesRedeemed  Int                @default(0)
  expiresAt      DateTime?
  active         Boolean            @default(true)
  note           String?
  createdAt      DateTime           @default(now())
  redemptions    CouponRedemption[]
}

model CouponRedemption {
  id          String   @id @default(cuid())
  couponId    String
  coupon      Coupon   @relation(fields: [couponId], references: [id], onDelete: Cascade)

model HostingNode {
  id             String            @id @default(cuid())
  name           String            @unique
  publicIp       String // the shared IP every account's domains point at
  sshHost        String // host/IP we SSH to (may differ from publicIp on NAT)
  sshPort        Int               @default(22)
  // Root credentials to provision on the box. Encrypted at rest, like server
  // root passwords. Exactly one of these is used.
  rootPasswordEnc String?
  hostnameFqdn   String? // e.g. srv12.nxeon.cloud — a CNAME target / cert SAN
  // Capacity for the account scheduler (least-loaded placement).
  maxAccounts    Int               @default(200)
  diskTotalGB    Int               @default(500)
  enabled        Boolean           @default(true)
  status         HostingNodeStatus @default(ONLINE)
  lastSeenAt     DateTime?
  // Node hardening (runs onboard-hosting-node.sh over the platform's own SSH):
  // NONE | QUEUED | RUNNING | DONE | FAILED. Admin-triggered; the worker sweep
  // picks up QUEUED nodes, streams the script, and records the tail + timestamp.
  hardenStatus   String            @default("NONE")
  hardenedAt     DateTime?
  hardenLog      String?
  createdAt      DateTime          @default(now())
  accounts       HostingAccount[]
}

/// A shared-hosting product tier (Starter / Plus / Pro web hosting), priced well
/// below a VPS and sold by resource limits rather than a VM size.
model HostingPlan {
  id            String           @id @default(cuid())
  slug          String           @unique
  name          String
  priceCents    Int
  diskGB        Int              @default(10)
  maxSites      Int              @default(1) // addon domains this account may host
  maxDatabases  Int              @default(1)
  bandwidthTB   Float            @default(1)
  // Bundled email mailboxes included with the plan. -1 = unlimited. Provisioned
  // on our own Nxeon Mail (Mailcow) backend when the account is created.
  mailboxes     Int              @default(1)
  // Marketing flags surfaced on the plan cards.
  freeMigration Boolean          @default(false) // "we move your existing site free"
  featured      Boolean          @default(false) // "Most popular" highlight
  tagline       String           @default("")     // one-line pitch under the plan name
  phpVersions   String           @default("8.3") // comma-separated allowed PHP versions
  active        Boolean          @default(true)
  sortOrder     Int              @default(0)
  createdAt     DateTime         @default(now())
  accounts      HostingAccount[]
}

enum HostingAccountStatus {
  PENDING // created, waiting for the provisioner
  PROVISIONING
  ACTIVE
  SUSPENDED
  FAILED
  DELETING
}

/// One customer's isolated shared-hosting account on a HostingNode: a jailed
/// Linux user with its own PHP-FPM pool, disk quota, primary domain and (later)
/// additional sites / databases / mailboxes. The unit of isolation and billing.
model HostingAccount {
  id            String               @id @default(cuid())
  userId        String
  user          User                 @relation(fields: [userId], references: [id], onDelete: Cascade)
  hostingNodeId String
  node          HostingNode          @relation(fields: [hostingNodeId], references: [id])
  planId        String
  plan          HostingPlan          @relation(fields: [planId], references: [id])
  // The jailed system username on the box (derived, unique per node). All the
  // account's files live under /home/<username>; its FPM pool runs AS this user.
  username      String
  primaryDomain String // the account's main domain (name-based vhost server_name)
  status        HostingAccountStatus @default(PENDING)
  // Effective quota snapshot (copied from the plan at creation so a plan edit
  // doesn't silently re-quota live accounts).
  diskQuotaMB   Int
  maxSites      Int
  maxDatabases  Int
  // PHP version the account's FPM pool runs (within the plan's allowed set).
  phpVersion    String               @default("8.3")
  // HTTPS: set once a per-domain Let's Encrypt cert is issued (SNI on the shared
  // IP). The SSL sweep flips this after the domain resolves to us.
  sslActive     Boolean              @default(false)
  // Live disk/inode usage, refreshed by hostingUsageSweep (null until first
  // measured). Powers the real usage meters in the customer panel.
  diskUsedMB    Int?
  inodesUsed    Int?
  usageAt       DateTime?
  // Serve-verification health, refreshed by hostingHealthSweep (null until first
  // checked). serveHttpOk/serveHttpsOk record whether nginx actually answers on
  // 80/443 for this domain from the node — the guardrail against a customer ever
  // seeing ERR_CONNECTION_REFUSED while the panel claims "active". healthNote is a
  // short human string for the DNS→HTTPS stepper; healthCheckedAt timestamps it.

model Server {
  id                  String        @id @default(cuid())
  name                String
  label               String? // customer-facing nickname (rename)
  hostname            String
  vmid                Int?          @unique
  status              ServerStatus  @default(PENDING)
  ipAddress           String?       @unique
  sshPort             Int?          @unique
  rootPassword        String?
  rootPasswordEnc     String?
  isFree              Boolean       @default(false)
  autoRenew           Boolean       @default(true)
  gameVariant         String? // game-server type/loader (e.g. paper, carbon, bepinex) — see lib/game-config
  gameConfig          Json? // per-game settings values (validated against the family schema)
  suspendedNote       String?
  // WHY a server is suspended: "UNPAID" | "ABUSE" | "ADMIN". Null = never suspended.
  //
  // `suspendedNote` used to be the only signal, and nothing consumed it, so every
  // suspension looked identical to the billing engine. Two live consequences:
  // (1) `terminateOverdue` selected on `status: "SUSPENDED"` alone, while the
  //     renewal sweep EXCLUDES suspended servers — so an admin suspending a
  //     paid-up customer pending an investigation meant they were never charged,
  //     never warned, their term lapsed, and 13 days later their VM and all its
  //     data were destroyed with a "prolonged non-payment" notice they had never
  //     been given a chance to act on.
  // (2) `renewNow` auto-unsuspended ANY suspended server on payment, so a spammer
  //     suspended for outbound abuse could pay and put themselves straight back
  //     on the network.
  // Both now scope strictly to UNPAID.
  suspendReason       String?
  expiresAt           DateTime?
  // ---- Dunning (failed auto-charge retry state) ----
  // dunningStage counts CARD ATTEMPTS THAT HAVE FAILED for the current unpaid
  // period: 0 = nothing owed / paid, 1..N = that many failures. Reset to 0 the
  // moment a renewal succeeds. `dunningNextAt` gates the next retry so a
  // 5-minute billing sweep cannot burn every retry in a quarter of an hour, and
  // `dunningPayUrl` is a hosted Checkout link emailed to the customer so they can
  // clear the balance themselves (also how 3-D Secure challenges are satisfied).
  dunningStage        Int           @default(0)
  dunningNextAt       DateTime?
  dunningPayUrl       String?
  createdAt           DateTime      @default(now())
  updatedAt           DateTime      @updatedAt
  userId              String
  user                User          @relation(fields: [userId], references: [id])
  nodeId              String?
  node                Node?         @relation(fields: [nodeId], references: [id])
  bwInBytes           BigInt        @default(0)
  bwOutBytes          BigInt        @default(0)
  abuseBwMark         BigInt? // last bwOutBytes sample, for outbound-rate abuse detection
  abuseBwMarkAt       DateTime? // when abuseBwMark was taken
  bwWindowStart       DateTime      @default(now())
  termMonths          Int           @default(1) // 1=monthly, 12=annual, 24=biennial, 36=triennial
  /// PERCENT OFF the term-discounted monthly rate that the months currently sitting
  /// between `now` and `expiresAt` were ACTUALLY sold at. This is the rate basis
  /// every proration must price against (lib/proration.ts).
  ///
  /// WHY IT EXISTS (2026-07-26). `prorateDeltaCents` defaulted its rate basis to
  /// `currentPromo(now)` — whatever seasonal promo happened to be running at the
  /// instant a resize was priced. Promos rotate by calendar date from a 15% Launch
  /// Sale to 45% for Cyber Monday, so a customer could upgrade during Cyber Monday
  /// (delta priced at 55% of the honest rate, small charge) and downgrade during
  /// the Launch Sale (delta priced at 85%, large credit) and pocket the 30-point
  /// spread x plan delta x every remaining month — repeatable every promo cycle,
  /// self-service, with the platform's own marketing calendar as the schedule.
  /// lib/promotions.ts is explicit that a promo is a FIRST-TERM intro discount that
  /// renewals never receive, so pricing a mid-term change off today's promo was
  /// wrong even before it was exploitable.
  ///
  /// WHY A PERCENT AND NOT A CENTS RATE. Proration is a DIFFERENCE between two
  /// plans' rates. A stored $/mo figure prices only the plan the server is on and
  /// says nothing about the plan it is moving to, so the other half of the
  /// subtraction would still need a basis invented for it — which is the bug. A
  /// percent is a rate BASIS that applies to any plan price, so both halves of the
  /// delta come from this one persisted number and the round trip is symmetric by
  /// construction rather than by convention. It also survives a plan change with no
  /// write at all: the customer keeps the rate they bought at, so up-then-down is
  /// exactly zero.
  ///
  ///   0   = full price. What BOTH renewal paths bill (worker/billing.ts sweep and
  ///         lib/actions.ts renewNow charge `vpsTermPriceCents` with no promo), and
  ///         what a flat-priced game plan is sold at.
  ///   1-99= a genuine intro/seasonal discount, or a blend of paid and gifted
  ///         months (see prorateBlendPercent in lib/proration.ts).
  ///   100 = gifted. Nothing was paid for these months, so nothing may prorate out
  ///         of them — an admin extension/free grant records this.
  ///   NULL= unknown. Only on rows that predate this column; resolved by an
  ///         EXPLICIT conservative fallback (`resolveTermPromoPercent`), never by
  ///         falling through to today's promo, because that IS the bug above.
  ///
  /// FLOAT, not Int, even though every promo in the catalogue is a whole number.
  /// Blending a renewal into a part-used term lands on halves: 36 months at 45% off
  /// plus 36 renewed at full price is exactly 22.5% off, and rounding that to 23
  /// quietly shaves $7.20 off a $1,071.36 credit. A first term still stores the
  /// promo's exact integer, so the column reads the same for the common case.
  termPromoPercent    Float?
  /// PERCENT the ANNUAL (12-month) commitment discount was set to when THIS server's
  /// term was sold — a snapshot of `annual_discount_percent` (lib/annual-discount.ts)
  /// frozen at the moment of sale, exactly like `termPromoPercent` freezes the seasonal
  /// rate.
  ///
  /// WHY IT EXISTS. The annual discount became an admin-configurable setting, read LIVE
  /// by proration (lib/proration.ts, via `vpsEffectiveMonthly`). Both halves of a resize
  /// round trip therefore priced against whatever the setting held at the instant each
  /// half ran: an admin nudging `annual_discount_percent` between a customer's upgrade
  /// and their downgrade made the credit and the charge disagree, so an annual server's
  /// up-then-down no longer netted to zero. Freezing the rate the server was SOLD at and
  /// reading THAT from both proration directions makes the round trip symmetric by
  /// construction, the same way `termPromoPercent` does for the promo rate.
  ///
  ///   NULL = pre-existing row (predates this column) OR a non-annual/flat-priced server
  ///          that never had an annual discount. Proration falls back to the LIVE setting
  ///          for these — identical maths for every non-annual term, and the best
  ///          available basis for a legacy annual row.
  annualDiscountPct   Float?
  /// GB of root disk purchased BEYOND the plan's `diskGB`. The server's EFFECTIVE
  /// disk is always `plan.diskGB + extraDiskGB`, so the extra survives a plan
  /// resize (it is additive to whichever plan the server sits on). Growth is

