function pveRequest(
  method: "GET" | "POST" | "PUT" | "DELETE",
  path: string,
  params?: Record<string, string | number | undefined>
) {
  return pveRequestTo(BASE, TOKEN, method, path, params);
}

export const pve = {
  get: (path: string, params?: Record<string, any>) => pveRequest("GET", path, params),
  post: (path: string, params?: Record<string, any>) => pveRequest("POST", path, params),
  put: (path: string, params?: Record<string, any>) => pveRequest("PUT", path, params),
  del: (path: string, params?: Record<string, any>) => pveRequest("DELETE", path, params),
};

export const node = NODE;

/** Connection details for a specific Node row (see Prisma `Node`). */
export type NodeConn = {
  apiUrl: string;
  pveNode: string;
  tokenId: string;
  tokenSecret: string;
};

export type PveClient = {
  get: (path: string, params?: Record<string, any>) => Promise<any>;
  post: (path: string, params?: Record<string, any>) => Promise<any>;
  put: (path: string, params?: Record<string, any>) => Promise<any>;
  del: (path: string, params?: Record<string, any>) => Promise<any>;
  node: string;
  waitForTask: (upid: string, timeoutMs?: number) => Promise<void>;
  nextVmid: () => Promise<number>;
  vmStatus: (vmid: number) => Promise<any>;
};

/** Build a Proxmox client bound to a specific node. Use in the worker for multi-node. */
export function pveFor(conn: NodeConn): PveClient {
  const token = `PVEAPIToken=${conn.tokenId}=${conn.tokenSecret}`;
  const req = (m: "GET" | "POST" | "PUT" | "DELETE", path: string, params?: Record<string, any>) =>
    pveRequestTo(conn.apiUrl, token, m, path, params);
  const client: PveClient = {
    get: (p, params) => req("GET", p, params),
    post: (p, params) => req("POST", p, params),
    put: (p, params) => req("PUT", p, params),
    del: (p, params) => req("DELETE", p, params),
    node: conn.pveNode,
    async waitForTask(upid: string, timeoutMs = 300_000) {
      const start = Date.now();
      while (Date.now() - start < timeoutMs) {
        const status = await req("GET", `/nodes/${conn.pveNode}/tasks/${encodeURIComponent(upid)}/status`);
        if (status.status === "stopped") {
          if (status.exitstatus !== "OK") throw new Error(`Proxmox task failed: ${status.exitstatus}`);
          return;
        }
        await new Promise((r) => setTimeout(r, 2000));
      }
      throw new Error(`Proxmox task timed out: ${upid}`);
    },
    async nextVmid() {
      return Number(await req("GET", "/cluster/nextid"));
    },
    async vmStatus(vmid: number) {
      return req("GET", `/nodes/${conn.pveNode}/qemu/${vmid}/status/current`);
    },
  };
  return client;
}

