export async function listVms(): Promise<any[]> {
  return pve.get(`/nodes/${NODE}/qemu`);
}

/** Time-series metrics. timeframe: hour | day | week | month | year.
 *  Pass the server's node connection — vmids can collide across nodes, so a
 *  same-numbered VM on another node would otherwise leak that tenant's series. */
export async function vmRrd(vmid: number, timeframe = "hour", conn?: PveClient): Promise<any[]> {
  const c = conn ?? pve;
  const node = conn ? conn.node : NODE;
  return c.get(`/nodes/${node}/qemu/${vmid}/rrddata`, { timeframe, cf: "AVERAGE" });
}

export async function nodeRrd(timeframe = "hour"): Promise<any[]> {
  return pve.get(`/nodes/${NODE}/rrddata`, { timeframe, cf: "AVERAGE" });
}

// ---------------------------------------------------------------------------
// In-guest disk usage via the QEMU guest agent (get-fsinfo)
// ---------------------------------------------------------------------------

/** Real filesystem usage as reported from *inside* the guest. */
export type GuestDiskUsage = { usedBytes: number; totalBytes: number };

/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`). */
export type GuestAgentClient = {
  get: (path: string, params?: Record<string, any>) => Promise<any>;
};

// Pseudo / virtual filesystems that don't represent real on-disk usage and must
// never be picked as the root filesystem. Matched against the fsinfo `type`.
const PSEUDO_FS_TYPES = new Set([
  "squashfs", "tmpfs", "devtmpfs", "overlay", "overlayfs", "vfat", "msdos",
  "proc", "sysfs", "cgroup", "cgroup2", "debugfs", "mqueue", "hugetlbfs",
  "fusectl", "pstore", "autofs", "binfmt_misc", "tracefs", "configfs",
  "securityfs", "ramfs", "nsfs", "efivarfs", "fuse.snapfuse", "iso9660",
]);

/** Is this mountpoint one we should ignore even if the type looks real? */
function isIgnorableMount(mountpoint: string): boolean {
  const mp = String(mountpoint ?? "");
  return (
    mp === "/boot" ||
    mp.startsWith("/boot/") ||
    mp.startsWith("/snap") ||
    mp.startsWith("/var/lib/docker") ||
    mp.startsWith("/run") ||
    mp.startsWith("/dev") ||
    mp.startsWith("/sys") ||
    mp.startsWith("/proc")
  );
}

/**
 * Query the QEMU guest agent's `get-fsinfo` and return the REAL root filesystem
 * usage (the entry mounted at "/", excluding pseudo/boot/loop filesystems).
 *
 * Proxmox RRD's `disk` field is 0 for QEMU VMs — the hypervisor can't see
 * in-guest usage — so this agent call is the only source of real used/total
 * bytes. Best-effort: returns null on any error or when the agent isn't ready
 * (never throws), so a missing agent degrades cleanly to the provisioned-size
 * fallback. In SANDBOX returns a synthetic, gently-varying realistic value.
 *
 * @param sandboxTotalBytes only used to size the synthetic sandbox value.
 */

import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { pve, node as defaultNode, pveFor, getGuestDiskUsage } from "../lib/proxmox";
import { effectiveDiskGB } from "../lib/extra-disk";
import {
  BW_PERIOD_MS,
  creditFromCounters,
  integrateRrdBytes,
  readBwMeterHealth,
  recordBwSweep,
  type BwSample,
} from "../lib/bandwidth";
import {
  nodeStorageUsage,
  nodeRamUsage,
  backupSummary,
  stuckJobs,
  workerHealth,
  sampleHealth,
  fmtAge,
  DISK_WARN_RATIO,
  RAM_WARN_RATIO,
  BACKUP_STALE_MS,
  QUEUE_BACKLOG_ALERT,
  STUCK_JOB_MS,
} from "../lib/monitoring";

/**
 * Monitoring sweep — run periodically from the worker loop. Read-only checks
 * that raise dashboard notifications for all ADMINs when a threshold trips.
 *
 * Notifications are de-duplicated by title within a rolling window so a
 * persistent condition (e.g. a node stuck at 90% disk) alerts once every few
 * hours rather than every sweep.
 */

const DEDUPE_HOURS = Number(process.env.NXEON_ALERT_DEDUPE_HOURS ?? 3);

/**
 * Fan a single alert out to every ADMIN, unless an identically-titled alert
 * already went out within the dedupe window.
 */
export async function notifyAdmins(
  title: string,
  body: string,
  href = "/admin/monitoring"
): Promise<void> {
  const since = new Date(Date.now() - DEDUPE_HOURS * 60 * 60_000);
  const recent = await db.notification.findFirst({
    where: { title, createdAt: { gt: since } },
    select: { id: true },
  });
  if (recent) return;

  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length === 0) return;

  await db.notification.createMany({
    data: admins.map((a) => ({ userId: a.id, title, body, href })),
  });
}

// Keep in-guest disk samples for ~5 weeks so the 30-day chart window always has
// history without letting the table grow unbounded.
const DISK_SAMPLE_RETENTION_DAYS = 35;
const GB = 1024 ** 3;

/**
 * Sample real in-guest disk usage for every RUNNING VM via the QEMU guest agent
 * and persist a point into ServerDiskSample. Runs on the monitor cadence.
 *
 * Best-effort throughout: a missing/not-ready guest agent yields null and is
 * simply skipped — it never errors the sweep. In SANDBOX getGuestDiskUsage
 * returns a synthetic value, so staging still builds a realistic history.
 * Also prunes samples older than the retention window each pass.
 */
export async function sampleServerDisks(): Promise<void> {
  // Retention prune first (cheap, and keeps the table bounded even if sampling
  // below throws for every server).
  try {
    const cutoff = new Date(Date.now() - DISK_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
    await db.serverDiskSample.deleteMany({ where: { ts: { lt: cutoff } } });
  } catch (e) {
    console.error("[monitor] disk-sample prune error", e);
  }

  let servers: Array<{ id: string; vmid: number | null; node: any; extraDiskGB: number; plan: { diskGB: number } }>;
  try {
    servers = await db.server.findMany({
      where: { status: "RUNNING", vmid: { not: null } },
      select: {
        id: true,
        vmid: true,
        extraDiskGB: true,
        plan: { select: { diskGB: true } },
        node: {
          select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true },
        },
      },
    });
  } catch (e) {
    console.error("[monitor] disk-sample: list servers error", e);
    return;
  }

  for (const s of servers) {
    if (s.vmid == null) continue;
    try {
      const client = s.node
        ? pveFor({
            apiUrl: s.node.apiUrl,
            pveNode: s.node.pveNode,
            tokenId: s.node.tokenId,
            tokenSecret: s.node.tokenSecret,
          })
        : pve;
      const pnode = s.node?.pveNode ?? defaultNode;
      const usage = await getGuestDiskUsage(client, pnode, s.vmid, effectiveDiskGB(s.plan.diskGB, s.extraDiskGB) * GB);
      if (!usage) continue; // agent not ready — skip, no error
      await db.serverDiskSample.create({
        data: {
          serverId: s.id,
          usedBytes: BigInt(Math.max(0, Math.round(usage.usedBytes))),
          totalBytes: BigInt(Math.max(0, Math.round(usage.totalBytes))),
        },
      });
    } catch (e) {
      console.error(`[monitor] disk-sample error for server ${s.id}`, e);
    }
  }
}

/**
 * Persist a HealthSample snapshot per component and advance the auto-incident
 * state machine (see lib/monitoring.ts → sampleHealth). Runs on the monitor
 * cadence, ALONGSIDE sampleServerDisks — NOT inside monitorSweep, so it keeps
 * building the /status uptime + incident history the same way disk sampling
 * keeps building the customer chart. Errors are swallowed here so a probe hiccup
 * never disturbs the worker's serial job loop.
 *
 * NOTE: like sampleServerDisks, this runs regardless of SANDBOX so staging also
 * accrues history. In SANDBOX the Proxmox probe may read "down" (no real node);
 * that is honest, not fabricated, and simply surfaces as a staging incident.
 */
export async function sampleHealthSweep(): Promise<void> {
  try {
    await sampleHealth();
  } catch (e) {
    console.error("[monitor] health-sample sweep error", e);
  }
}

// ---------------------------------------------------------------------------
// Bandwidth metering sweep
// ---------------------------------------------------------------------------

/**
 * Last counter sample per `serverId:vmid`, in worker memory.
 *
 * Deliberately not persisted: prisma/schema.prisma has no column for a raw
 * per-VM counter, and the two obvious substitutes are worse than a cold start —
 * the `Setting` KV is handed wholesale to the admin settings page (it would ship
 * a blob of every server's counters to the browser), and reusing
 * `abuseBwMark` would break the abuse window it exists for. A worker restart
 * therefore loses the baseline; `backfillGap` recovers the interval from RRD so
 * the restart costs at most the newest (still-filling) RRD bucket instead of a
 * whole sweep interval.
 *
 * Keyed by vmid as well as serverId so a reinstall or migration onto a different
 * vmid can never be compared against the old VM's counters.
 */
const bwBaselines = new Map<string, BwSample>();

/**
 * Where the last sweep stopped. The sweep is time-bounded, so on a large fleet it
 * may not reach every server; resuming from the cursor rather than always
 * restarting at the first row is what stops the tail of the list from being
 * silently never metered — a server whose usage always reads 0 because nobody
 * ever looked at it is precisely the failure this whole change exists to fix.
 */
let bwCursor = 0;

/**
 * Sampling runs INLINE in the worker's strictly serial job loop: every second
 * spent here is a second no customer job runs, so the sweep is hard-bounded.
 * A Proxmox node that hangs must cost one timeout, not the queue.
 */
const BW_CALL_TIMEOUT_MS = 8_000;
const BW_SWEEP_BUDGET_MS = 45_000;
/** RRD back-fill is ~10x the payload of a status read, so cap it per sweep. */
const BW_MAX_BACKFILLS_PER_SWEEP = 50;
/** Below this a gap is not worth an extra API call. */
const BW_BACKFILL_MIN_GAP_MS = 2 * 60_000;
/** `timeframe=hour` holds 60 x 60s buckets; beyond that the gap is unrecoverable. */
const BW_RRD_WINDOW_MS = 60 * 60_000;

/**
 * Bound one Proxmox call. Note this abandons the promise rather than cancelling
 * the request (lib/proxmox takes no AbortSignal) — the point is that the sweep
 * moves on, not that the socket closes.
 */
function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(
      () => reject(new Error(`proxmox call timed out after ${ms}ms: ${what}`)),
      ms
    );
    p.then(
      (v) => {
        clearTimeout(timer);
        resolve(v);
      },
      (e) => {
        clearTimeout(timer);
        reject(e);
      }
    );
  });
}

type BwClient = { get: (path: string, params?: Record<string, any>) => Promise<any> };

/**
 * Meter every RUNNING VM's network counters onto its Server row.
 *
 * Writes `bwInBytes` / `bwOutBytes` (cumulative for the current metering period)
 * and `bwWindowStart` (the period marker). Nothing wrote these before, which is
 * why the customer's bandwidth panel read a permanent zero and worker/abuse.ts
 * could never fire — see lib/bandwidth.ts for the full history.
 *
 * READ-ONLY against Proxmox: `status/current` and `rrddata`, never a mutation.
 * Best-effort per server — one unreachable node must not cost the whole sweep.
 */
export async function sampleServerBandwidth(): Promise<void> {
  if (SANDBOX) return; // no real VMs, therefore no real traffic to meter

  const sweepStartMs = Date.now();
  let health;
  try {
    health = await readBwMeterHealth(sweepStartMs);
  } catch (e) {
    console.error("[bandwidth] could not read meter markers", e);
    return;
  }
  // End of the previous sweep — where a cold-start back-fill starts counting.
  // Only the cold path uses it; the warm path uses each baseline's own
  // timestamp, so a sweep cadence that drifts (or a sweep that gets skipped
  // entirely) stays correct without assuming a fixed interval.
  const priorSweepMs = health.lastAt?.getTime() ?? null;

  let servers: Array<{
    id: string;
    hostname: string;
    vmid: number | null;
    bwWindowStart: Date;
    node: {
      pveNode: string;
      apiUrl: string;
      tokenId: string;
      tokenSecret: string;
    } | null;
  }>;
  try {
    servers = await db.server.findMany({
      where: { status: "RUNNING", vmid: { not: null } },
      select: {
        id: true,
        hostname: true,
        vmid: true,
        bwWindowStart: true,
        node: { select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true } },
      },
      orderBy: { id: "asc" }, // stable order, so the cursor below means something
    });
  } catch (e) {
    console.error("[bandwidth] list servers error", e);
    return;
  }

  // On the very first sweep there is no stored start yet; treat now as the start
  // so window normalisation below has a truthful lower bound to work with.
  const startedAtMs = health.startedAt?.getTime() ?? sweepStartMs;

  let sampled = 0;
  let backfills = 0;
  let backfilled = false;
  let gapDetected = false;

  // Every RUNNING VM's key, whether or not this sweep reaches it, so the prune at
  // the end can't throw away a baseline we still want.
  const liveKeys = new Set(
    servers.filter((s) => s.vmid != null).map((s) => `${s.id}:${s.vmid}`)
  );

  const total = servers.length;
  const startIdx = total > 0 ? bwCursor % total : 0;
  let visited = 0;

  for (let i = 0; i < total; i++) {
    const s = servers[(startIdx + i) % total];
    if (s.vmid == null) {
      visited++;
      continue;
    }
    const key = `${s.id}:${s.vmid}`;

    if (Date.now() - sweepStartMs > BW_SWEEP_BUDGET_MS) {
      // Out of budget. Baselines are kept, so the servers we skipped are simply
      // metered over a longer interval next sweep — no traffic is lost — and the
      // cursor makes the next sweep start where this one stopped.
      console.warn(
        `[bandwidth] sweep budget exhausted after ${visited} of ${total} servers; ` +
          `resuming from there next sweep`
      );
      break;
    }
    visited++;

    const client: BwClient = s.node
      ? pveFor({
          apiUrl: s.node.apiUrl,
          pveNode: s.node.pveNode,
          tokenId: s.node.tokenId,
          tokenSecret: s.node.tokenSecret,
        })
      : pve;
    const pnode = s.node?.pveNode ?? defaultNode;

    try {
      const cur = await withTimeout(
        client.get(`/nodes/${pnode}/qemu/${s.vmid}/status/current`),
        BW_CALL_TIMEOUT_MS,
        `status/current vm ${s.vmid}`
      );
      // Our DB says RUNNING but Proxmox is authoritative. A stopped VM reports
      // netin/netout 0, and treating that as a counter rollback would be noise.
      if (String(cur?.status ?? "") !== "running") {
        bwBaselines.delete(key);
        continue;
      }
      const netin = Number(cur?.netin);
      const netout = Number(cur?.netout);
      if (!Number.isFinite(netin) || !Number.isFinite(netout)) {
        // Node too old / unexpected payload: no counters, nothing to meter.
        continue;
      }
      const sample: BwSample = {
        netin,
        netout,
        uptimeSec: Number(cur?.uptime) || 0,
        pid: Number.isFinite(Number(cur?.pid)) ? Number(cur.pid) : null,
        atMs: Date.now(),
      };

      const prev = bwBaselines.get(key);
      bwBaselines.set(key, sample);
      sampled++;

      let inBytes = 0;
      let outBytes = 0;

      if (prev) {
        const credit = creditFromCounters(prev, sample);
        inBytes = credit.inBytes;
        outBytes = credit.outBytes;
        if (credit.reason !== "delta") {
          // Logged, never silent: each of these means the customer's total is
          // missing traffic we could not attribute, and an operator chasing a
          // suspiciously low figure needs to see it.
          console.warn(
            `[bandwidth] ${s.hostname} (vm ${s.vmid}) counter ${credit.reason} — ` +
              `credited ${inBytes} in / ${outBytes} out (prev ${prev.netin}/${prev.netout} ` +
              `pid ${prev.pid} up ${prev.uptimeSec}s → now ${sample.netin}/${sample.netout} ` +
              `pid ${sample.pid} up ${sample.uptimeSec}s)`
          );
        }
      } else if (priorSweepMs !== null) {
        // Cold start (worker restarted, or this VM just came up). The counter
        // baseline is gone, so recover the interval from RRD rate data instead
        // of dropping it — without this, every redeploy silently erases up to a
        // sweep interval of every customer's usage.
        const gapMs = sweepStartMs - priorSweepMs;
        if (gapMs > BW_RRD_WINDOW_MS) {
          // Longer than RRD's hour window: part of this gap is unrecoverable.
          // Recorded so the UI can admit the period under-reports.
          gapDetected = true;
        }
        if (gapMs >= BW_BACKFILL_MIN_GAP_MS && backfills < BW_MAX_BACKFILLS_PER_SWEEP) {
          backfills++;
          const filled = await backfillGap(client, pnode, s.vmid, priorSweepMs, sample.atMs);
          if (filled) {
            inBytes = filled.inBytes;
            outBytes = filled.outBytes;
            backfilled = true;
          }
        }
      }

      const roundedIn = Math.max(0, Math.round(inBytes));
      const roundedOut = Math.max(0, Math.round(outBytes));

      // The period marker predates metering on every row created before this
      // sweep existed (it defaults to the row's creation date), so pull it
      // forward to the moment measurement actually began. Without this the UI
      // would claim these bytes cover months we never watched.
      const needsWindowFix = s.bwWindowStart.getTime() < startedAtMs;
      const effectiveWindowMs = Math.max(s.bwWindowStart.getTime(), startedAtMs);
      const roll = sample.atMs - effectiveWindowMs >= BW_PERIOD_MS;

      if (roundedIn === 0 && roundedOut === 0 && !roll && !needsWindowFix) {
        continue; // nothing to record — skip the write entirely
      }

      if (roll) {
        // New period: these bytes belong to the period starting now.
        await db.server.update({
          where: { id: s.id },
          data: {
            bwInBytes: BigInt(roundedIn),
            bwOutBytes: BigInt(roundedOut),
            bwWindowStart: new Date(sample.atMs),
          },
        });
      } else {
        await db.server.update({
          where: { id: s.id },
          data: {
            bwInBytes: { increment: BigInt(roundedIn) },
            bwOutBytes: { increment: BigInt(roundedOut) },
            ...(needsWindowFix ? { bwWindowStart: new Date(startedAtMs) } : {}),
          },
        });
      }
    } catch (e) {
      console.error(`[bandwidth] sample error for ${s.hostname} (vm ${s.vmid})`, e);
    }
  }

  bwCursor = total > 0 ? (startIdx + visited) % total : 0;

  // Drop baselines for VMs no longer in the RUNNING set (deleted, stopped,
  // suspended, reinstalled onto a new vmid) so the map stays bounded. Servers
  // skipped by the time budget ARE in liveKeys, so their baselines survive.
  for (const key of [...bwBaselines.keys()]) {
    if (!liveKeys.has(key)) bwBaselines.delete(key);
  }

  try {
    await recordBwSweep({
      sweepEndMs: Date.now(),
      sampled,
      candidates: total,
      gapDetected,
      backfilled,
      hadStartedAt: health.startedAt !== null,
    });
  } catch (e) {
    console.error("[bandwidth] could not record sweep markers", e);
  }
}

/**
 * Recover a metering gap for one VM from RRD rate data.
 *
 * Returns null (rather than 0) when RRD had nothing usable, so the caller does
 * not treat "no data" as "no traffic". Bounded by the same per-call timeout as
 * the counter read.
 */
async function backfillGap(
  client: BwClient,
  pnode: string,
  vmid: number,
  fromMs: number,
  toMs: number
): Promise<{ inBytes: number; outBytes: number } | null> {
  try {
    const rows = await withTimeout(
      client.get(`/nodes/${pnode}/qemu/${vmid}/rrddata`, { timeframe: "hour", cf: "AVERAGE" }),
      BW_CALL_TIMEOUT_MS,
      `rrddata vm ${vmid}`
    );
    const filled = integrateRrdBytes(
      Array.isArray(rows) ? rows : [],
      Math.floor(fromMs / 1000),
      Math.floor(toMs / 1000)
    );
    if (!filled) return null;
    return { inBytes: filled.inBytes, outBytes: filled.outBytes };
  } catch (e) {
    console.error(`[bandwidth] rrd back-fill failed for vm ${vmid}`, e);
    return null;
  }
}

export async function monitorSweep(): Promise<void> {
  if (SANDBOX) return; // no real nodes/Proxmox to monitor in the sandbox

  // 0. Bandwidth metering. Runs FIRST and inside monitorSweep on purpose:
  //    worker/index.ts calls monitorSweep() and then abuseSweep() in the same
  //    block, so metering this way guarantees the abuse detector reads counters
  //    from this sweep rather than the previous one — and needs no change to the
  //    worker loop, which other work owns.
  try {
    await sampleServerBandwidth();
  } catch (e) {
    console.error("[bandwidth] sweep error", e);
  }
  // 1. Node disk usage > threshold
  try {
    const storage = await nodeStorageUsage();
    for (const s of storage) {
      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
        const pct = Math.round(s.ratio * 100);
        await notifyAdmins(
          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
        );
      }
    }
  } catch (e) {
    console.error("[monitor] disk check error", e);
  }

  // 2. Node RAM pressure > threshold
  try {
    const ram = await nodeRamUsage();
    for (const r of ram) {
      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
        const pct = Math.round(r.ratio * 100);
        await notifyAdmins(
          `Memory pressure — ${r.node} at ${pct}%`,
          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
        );
      }
    }
  } catch (e) {
    console.error("[monitor] ram check error", e);
  }

  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
  try {
    const stuck = await stuckJobs();
    if (stuck.length > 0) {
      const mins = Math.round(STUCK_JOB_MS / 60_000);
      const lines = stuck
        .slice(0, 8)
        .map(
          (j) =>
            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
              Date.now() - j.updatedAt.getTime()
            )}`
        )
        .join("\n");
      await notifyAdmins(
        `Stuck jobs — ${stuck.length} running > ${mins}m`,
        `The worker has job(s) stuck in RUNNING:\n${lines}`
      );
    }
  } catch (e) {
    console.error("[monitor] stuck-job check error", e);
  }

  // 4. Worker liveness + pending-job backlog
  try {
    const wh = await workerHealth();
    if (wh.status === "down") {
      await notifyAdmins(
        "Worker appears stopped",
        wh.detail + ". Check the provisioning worker process."
      );
    }
    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
      await notifyAdmins(
        `Job backlog building — ${wh.queuedBacklog} queued`,
        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
      );
    }
  } catch (e) {
    console.error("[monitor] worker check error", e);
  }

  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
  try {
    const bk = await backupSummary();
    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
      const ageMs = Date.now() - bk.newestCtime * 1000;
      if (ageMs > BACKUP_STALE_MS) {
        await notifyAdmins(
          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
        );
      }
    }
  } catch (e) {
    console.error("[monitor] backup check error", e);
  }
}

import { db } from "./db";
import { pve, node as primaryNode, pveFor } from "./proxmox";
import type { Node } from "@prisma/client";
import { COMPONENT_LABELS, SEVERITY_LABEL, type HealthComponentKey } from "./status-copy";

/**
 * Shared, READ-ONLY monitoring helpers for Nxeon.
 *
 * Everything here is safe to call from server components (status page, admin
 * monitoring) and from the worker sweep (`worker/monitor.ts`). No mutations,
 * no secrets in the returned shapes — the public /status page renders off the
 * same `getHealth()` logic the API exposes.
 *
 * Proxmox access is strictly read-only: `GET /nodes/{node}/status` and
 * `GET /nodes/{node}/storage/{storage}/status` (+ backup content listing).
 */

export type CompStatus = "operational" | "degraded" | "down";
export type Component = { status: CompStatus; detail: string };

export type HealthReport = {
  web: Component;
  db: Component;
  worker: Component;
  proxmox: Component;
  checkedAt: string;
};

// ---- Thresholds (env-overridable) ---------------------------------------

/** Worker is expected to touch the queue within this window; older QUEUED work ⇒ down. */
export const WORKER_STALE_MS = Number(process.env.NXEON_WORKER_STALE_MS ?? 2 * 60_000);
/** A Job sitting in RUNNING longer than this is considered stuck. */
export const STUCK_JOB_MS = Number(process.env.NXEON_STUCK_JOB_MS ?? 15 * 60_000);
/** Storage usage above this fraction trips a disk-capacity alert. */
export const DISK_WARN_RATIO = Number(process.env.NXEON_DISK_WARN_RATIO ?? 0.85);
/** Node RAM usage above this fraction trips an alert. */
export const RAM_WARN_RATIO = Number(process.env.NXEON_RAM_WARN_RATIO ?? 0.9);
/** No fresh backup within this window ⇒ backups look stale. */
export const BACKUP_STALE_MS = Number(process.env.NXEON_BACKUP_STALE_MS ?? 48 * 60 * 60_000);
/** QUEUED backlog at/above this depth trips an alert. */
export const QUEUE_BACKLOG_ALERT = Number(process.env.NXEON_QUEUE_BACKLOG_ALERT ?? 25);

// ---- Small formatters ----------------------------------------------------

/** Compact human age from a millisecond duration. */
export function fmtAge(ms: number): string {
  if (ms < 0) ms = 0;
  const m = Math.floor(ms / 60_000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h`;
  const d = Math.floor(h / 24);
  return `${d}d ${h % 24}h`;
}

// ---- Proxmox targets (read-only) ----------------------------------------

type PveTarget = {
  label: string;
  pveNode: string;
  get: (path: string, params?: Record<string, any>) => Promise<any>;
  /** Distinct storages worth watching on this node. */
  storages: string[];
};

/**
 * Resolve the set of Proxmox nodes to poll. Prefers explicit `Node` rows
 * (multi-node), and falls back to the env-configured primary when none exist.
 */
export async function nodeTargets(): Promise<PveTarget[]> {
  const nodes = await db.node.findMany({
    where: { enabled: true },
    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
  });
  if (nodes.length === 0) {
    return [
      {
        label: primaryNode || "primary",
        pveNode: primaryNode,
        get: (p, pp) => pve.get(p, pp),
        storages: ["vmdata", "backup"],
      },
    ];
  }
  return nodes.map((n: Node) => {
    const client = pveFor({
      apiUrl: n.apiUrl,
      pveNode: n.pveNode,
      tokenId: n.tokenId,
      tokenSecret: n.tokenSecret,
    });
    const storages = [n.storageNvme, n.storageHdd, "backup"].filter(
      (v, i, a) => v && a.indexOf(v) === i
    );
    return { label: n.name, pveNode: n.pveNode, get: client.get, storages };
  });
}

export type StorageUsage = {
  node: string;
  storage: string;
  total: number;
  used: number;
  avail: number;
  ratio: number;
  reachable: boolean;
};

/** Per-node, per-storage disk usage (bytes). Unreachable storages are marked. */
export async function nodeStorageUsage(): Promise<StorageUsage[]> {
  const targets = await nodeTargets();
  const out: StorageUsage[] = [];
  for (const t of targets) {
    for (const storage of t.storages) {
      try {
        const st = await t.get(`/nodes/${t.pveNode}/storage/${storage}/status`);
        const total = Number(st?.total ?? 0);
        const used = Number(st?.used ?? 0);
        const avail = Number(st?.avail ?? Math.max(0, total - used));
        out.push({
          node: t.label,
          storage,
          total,
          used,
          avail,
          ratio: total > 0 ? used / total : 0,
          reachable: true,
        });
      } catch {
        out.push({ node: t.label, storage, total: 0, used: 0, avail: 0, ratio: 0, reachable: false });
      }
    }
  }
  return out;
}

export type NodeRam = {
  node: string;
  total: number;
  used: number;
  ratio: number;
  cpu: number;
  reachable: boolean;
};

/** Per-node RAM + CPU load from the node status endpoint. */
export async function nodeRamUsage(): Promise<NodeRam[]> {
  const targets = await nodeTargets();
  return Promise.all(
    targets.map(async (t) => {
      try {
        const s = await t.get(`/nodes/${t.pveNode}/status`);
        const total = Number(s?.memory?.total ?? 0);
        const used = Number(s?.memory?.used ?? 0);
        return {
          node: t.label,
          total,
          used,
          ratio: total > 0 ? used / total : 0,
          cpu: Number(s?.cpu ?? 0),
          reachable: true,
        };
      } catch {
        return { node: t.label, total: 0, used: 0, ratio: 0, cpu: 0, reachable: false };
      }
    })
  );
}

export type BackupSummary = {
  count: number;
  /** Unix seconds of the most recent backup (freshness signal). */
  newestCtime: number | null;
  /** Unix seconds of the oldest backup on disk. */
  oldestCtime: number | null;
  reachable: boolean;
};

/**
 * Summarise backups across all nodes' `backup` storage. Best-effort: if the
 * storage/content endpoint isn't available the node is simply skipped.
 */
export async function backupSummary(): Promise<BackupSummary> {
  const targets = await nodeTargets();
  let count = 0;
  let newest: number | null = null;
  let oldest: number | null = null;
  let reachable = false;
  for (const t of targets) {
    try {
      const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/backup/content`, {
        content: "backup",
      });
      reachable = true;
      for (const b of items ?? []) {
        const ct = Number(b?.ctime ?? 0);
        if (!ct) continue;
        count++;
        if (newest === null || ct > newest) newest = ct;
        if (oldest === null || ct < oldest) oldest = ct;
      }
    } catch {
      // storage/content not available on this node — skip
    }
  }
  return { count, newestCtime: newest, oldestCtime: oldest, reachable };
}

// ---- Worker / job health -------------------------------------------------

export type StuckJob = {
  id: string;
  type: string;
  updatedAt: Date;
  attempts: number;
  serverId: string | null;
  hostname: string | null;
};

/** Jobs stuck in RUNNING past the stuck threshold. */
export async function stuckJobs(): Promise<StuckJob[]> {
  const rows = await db.job.findMany({
    where: { status: "RUNNING", updatedAt: { lt: new Date(Date.now() - STUCK_JOB_MS) } },
    orderBy: { updatedAt: "asc" },
    take: 20,
    select: {
      id: true,
      type: true,
      updatedAt: true,
      attempts: true,
      serverId: true,
      server: { select: { hostname: true } },
    },
  });
  return rows.map((r) => ({
    id: r.id,
    type: r.type,
    updatedAt: r.updatedAt,
    attempts: r.attempts,
    serverId: r.serverId,
    hostname: r.server?.hostname ?? null,
  }));
}

export type WorkerHealth = {
  status: CompStatus;
  detail: string;
  newestUpdatedAt: Date | null;
  stuckRunning: number;
  queuedBacklog: number;
  staleQueued: number;
};

/**
 * Worker liveness inferred from the Job queue:
 *  - QUEUED work older than WORKER_STALE_MS that hasn't been picked up ⇒ down
 *    (the loop isn't draining the queue).
 *  - Jobs stuck RUNNING past STUCK_JOB_MS ⇒ degraded.
 *  - Otherwise operational (an empty/fresh queue is healthy, even if idle).
 */
export async function workerHealth(): Promise<WorkerHealth> {
  const now = Date.now();
  const [newest, stuckRunning, queuedBacklog, staleQueued] = await Promise.all([
    db.job.findFirst({ orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STUCK_JOB_MS) } } }),
    db.job.count({ where: { status: "QUEUED" } }),
    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - WORKER_STALE_MS) } } }),
  ]);

  let status: CompStatus = "operational";
  let detail = newest
    ? `last job update ${fmtAge(now - newest.updatedAt.getTime())} ago`
    : "idle — no jobs processed yet";

  if (staleQueued > 0) {
    status = "down";
    detail = `${staleQueued} job(s) queued but not picked up — worker may be stopped`;
  } else if (stuckRunning > 0) {
    status = "degraded";
    detail = `${stuckRunning} job(s) stuck running > ${Math.round(STUCK_JOB_MS / 60_000)}m`;
  }

  return {
    status,
    detail,
    newestUpdatedAt: newest?.updatedAt ?? null,
    stuckRunning,
    queuedBacklog,
    staleQueued,
  };
}

// ---- Component health (db / proxmox) ------------------------------------

async function dbHealth(): Promise<Component> {
  try {
    await db.$queryRaw`SELECT 1`;
    return { status: "operational", detail: "responding" };
  } catch (e: any) {
    return { status: "down", detail: String(e?.message ?? e).slice(0, 120) };
  }
}

async function proxmoxHealth(): Promise<Component> {
  const targets = await nodeTargets();
  let ok = 0;
  let fail = 0;
  for (const t of targets) {
    try {
      await t.get(`/nodes/${t.pveNode}/status`);
      ok++;
    } catch {
      fail++;
    }
  }
  if (ok === 0) return { status: "down", detail: "no Proxmox node reachable" };
  if (fail > 0) return { status: "degraded", detail: `${fail} of ${ok + fail} nodes unreachable` };
  return { status: "operational", detail: `${ok} node(s) reachable` };
}

/** Full health report — the source of truth for /api/health and /status. */
export async function getHealth(): Promise<HealthReport> {
  const [dbc, wh, px] = await Promise.all([dbHealth(), workerHealth(), proxmoxHealth()]);
  return {
    web: { status: "operational", detail: "serving requests" },
    db: dbc,
    worker: { status: wh.status, detail: wh.detail },
    proxmox: px,
    checkedAt: new Date().toISOString(),
  };
}

/** Roll the four components up into a single worst-of status. */
export function overallStatus(h: HealthReport): CompStatus {
  return worstStatus([h.web.status, h.db.status, h.worker.status, h.proxmox.status]);
}

// ===========================================================================
// History layer: HealthSample snapshots, uptime math, and StatusIncident state
//
// The four probes above are INSTANTANEOUS — they say what is true right now and
// keep no memory. Everything below turns that into history: the worker monitor
// calls sampleHealth() on its cadence to persist one HealthSample per component,
// and the readers compute uptime %, a bucketed timeline, and open/resolved
// incidents from those rows. All the arithmetic is factored into PURE functions
// (uptimeFromSamples / bucketTimeline / decideIncident) so it is unit-testable
// with an injected clock and injected samples, no DB required.
// ===========================================================================

/** The monitored components, as the string keys stored in HealthSample.component. */
export const HEALTH_COMPONENTS = ["web", "db", "worker", "proxmox"] as const;
export type HealthComponent = HealthComponentKey;

export type IncidentSeverity = "degraded" | "down" | "maintenance";

/** Consecutive unhealthy samples before an incident auto-opens. */
export const INCIDENT_OPEN_STREAK = Number(process.env.NXEON_INCIDENT_OPEN_STREAK ?? 3);
/** Consecutive healthy samples before an auto-incident auto-resolves. */
export const INCIDENT_RESOLVE_STREAK = Number(process.env.NXEON_INCIDENT_RESOLVE_STREAK ?? 2);
/** HealthSample rows older than this are pruned each sweep (keeps the 90-day window backed). */
export const HEALTH_SAMPLE_RETENTION_DAYS = Number(process.env.NXEON_HEALTH_RETENTION_DAYS ?? 95);
/** Default uptime / timeline window. */
export const UPTIME_WINDOW_MS = Number(process.env.NXEON_UPTIME_WINDOW_MS ?? 90 * 24 * 60 * 60_000);

/** Worst-of over a set of statuses (down > degraded > operational). */
export function worstStatus(statuses: CompStatus[]): CompStatus {
  if (statuses.includes("down")) return "down";
  if (statuses.includes("degraded")) return "degraded";
  return "operational";
}

// ---- Pure math (no DB, injected clock) ----------------------------------

/** Minimal shape the pure readers work on — a status stamped at a time. */
export type SampleLite = { status: CompStatus; ts: Date | string | number };

function tsMs(t: Date | string | number): number {
  return t instanceof Date ? t.getTime() : new Date(t).getTime();
}

export type UptimeResult = {
  /** Fraction operational over the window, 0..100. `null` = no samples yet ("collecting data"). */
  pct: number | null;
  total: number;
  up: number;
  degraded: number;
  down: number;
};

/**
 * Uptime % from samples in `[now - windowMs, now]`. Only `operational` counts as
 * up — degraded/down are both downtime. Returns `pct: null` when the window has
 * NO samples, so callers say "collecting data" instead of fabricating 100%.
 */
export function uptimeFromSamples(samples: SampleLite[], now: number, windowMs: number): UptimeResult {
  const cutoff = now - windowMs;
  let total = 0;
  let up = 0;
  let degraded = 0;
  let down = 0;
  for (const s of samples) {
    const t = tsMs(s.ts);
    if (t < cutoff || t > now) continue;
    total++;
    if (s.status === "operational") up++;
    else if (s.status === "degraded") degraded++;
    else down++;
  }
  return { pct: total === 0 ? null : (up / total) * 100, total, up, degraded, down };
}

export type TimelineBucket = {
  start: number;
  end: number;
  /** Worst status observed in the bucket, or `null` when no samples landed in it. */
  status: CompStatus | null;
  total: number;
};

/**
 * Split the window into `bucketCount` equal buckets and reduce each to its WORST
 * status (a single degraded reading in a day colours that day amber). Empty
 * buckets stay `null` — the strip renders them as "no data", never as green.
 */
export function bucketTimeline(
  samples: SampleLite[],
  now: number,
  windowMs: number,
  bucketCount: number
): TimelineBucket[] {
  const n = Math.max(1, Math.floor(bucketCount));
  const bucketMs = windowMs / n;
  const start0 = now - windowMs;
  const buckets: TimelineBucket[] = Array.from({ length: n }, (_, i) => ({
    start: start0 + i * bucketMs,
    end: start0 + (i + 1) * bucketMs,
    status: null,
    total: 0,
  }));
  for (const s of samples) {
    const t = tsMs(s.ts);
    if (t < start0 || t > now) continue;
    let idx = Math.floor((t - start0) / bucketMs);
    if (idx < 0) idx = 0;
    if (idx >= n) idx = n - 1;
    const b = buckets[idx];
    b.total++;
    b.status = b.status === null ? s.status : worstStatus([b.status, s.status]);
  }
  return buckets;
}

export type IncidentDecision =
  | { action: "open"; severity: "degraded" | "down" }
  | { action: "resolve" }
  | { action: "none" };

/**
 * The auto-incident state machine, pure and deterministic.
 *
 * `recent` is the most-recent-first run of a component's sample statuses (newest
 * at index 0). With no open incident, a leading run of >= INCIDENT_OPEN_STREAK
 * unhealthy samples opens one (severity = down if the newest is down, else
 * degraded). With one open, a leading run of >= INCIDENT_RESOLVE_STREAK healthy
 * samples resolves it. Anything else is a no-op — this is called every sweep, so
 * it must be idempotent once the streak condition is (un)met.
 */
export function decideIncident(recent: CompStatus[], hasOpenIncident: boolean): IncidentDecision {
  if (recent.length === 0) return { action: "none" };

  let unhealthyStreak = 0;
  for (const s of recent) {
    if (s !== "operational") unhealthyStreak++;
    else break;
  }
  let healthyStreak = 0;
  for (const s of recent) {
    if (s === "operational") healthyStreak++;
    else break;
  }

  if (!hasOpenIncident) {
    if (unhealthyStreak >= INCIDENT_OPEN_STREAK) {
      return { action: "open", severity: recent[0] === "down" ? "down" : "degraded" };
    }
    return { action: "none" };
  }
  if (healthyStreak >= INCIDENT_RESOLVE_STREAK) return { action: "resolve" };
  return { action: "none" };
}

/**
 * Public-safe copy for an auto-opened incident. Deliberately generic — it names
 * the friendly component and the severity, and never embeds the probe's raw
 * `detail` (which can carry host:port / upstream error text).
 */
export function autoIncidentCopy(
  component: HealthComponent,
  severity: "degraded" | "down"
): { title: string; body: string } {
  const name = COMPONENT_LABELS[component] ?? component;
  const what = severity === "down" ? "a service disruption" : "degraded performance";
  return {
    title: `${name}: ${SEVERITY_LABEL[severity]}`,
    body:
      `Our automated monitoring detected ${what} affecting ${name}. Engineers have been ` +
      `notified and this incident will update automatically as the component recovers.`,
  };
}

// ---- Snapshot writer (worker cadence) -----------------------------------

/**
 * Persist one HealthSample per component AND advance the auto-incident state
 * machine. Called on the worker monitor cadence (see worker/monitor.ts →
 * sampleHealthSweep). Cheap and idempotent: 4-row insert, one small read + at
 * most one write per component, plus a bounded retention prune.
 */
export async function sampleHealth(now: Date = new Date()): Promise<void> {
  const report = await getHealth();

  await db.healthSample.createMany({
    data: HEALTH_COMPONENTS.map((c) => ({
      component: c,
      status: report[c].status,
      detail: report[c].detail ? report[c].detail.slice(0, 240) : null,
      ts: now,
    })),
  });

  const lookback = Math.max(INCIDENT_OPEN_STREAK, INCIDENT_RESOLVE_STREAK, 1);
  for (const c of HEALTH_COMPONENTS) {
    const recentRows = await db.healthSample.findMany({
      where: { component: c },
      orderBy: { ts: "desc" },
      take: lookback,
      select: { status: true },
    });
    const recent = recentRows.map((r) => r.status as CompStatus);
    const open = await db.statusIncident.findFirst({
      where: { component: c, resolvedAt: null, auto: true },
      orderBy: { startedAt: "desc" },
    });
    const decision = decideIncident(recent, !!open);
    if (decision.action === "open" && !open) {
      const copy = autoIncidentCopy(c, decision.severity);
      await db.statusIncident.create({
        data: { component: c, severity: decision.severity, title: copy.title, body: copy.body, auto: true, startedAt: now },
      });
    } else if (decision.action === "resolve" && open) {
      await db.statusIncident.update({ where: { id: open.id }, data: { resolvedAt: now } });
    }
  }

  // Retention prune — best-effort, never blocks a sample.
  try {
    const cutoff = new Date(now.getTime() - HEALTH_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
    await db.healthSample.deleteMany({ where: { ts: { lt: cutoff } } });
  } catch (e) {
    console.error("[monitor] health-sample prune error", e);
  }
}

// ---- Readers (DB → pure math) -------------------------------------------

/** Uptime per component over the window. Keys are always the four components. */
export async function uptimeSummary(
  windowMs: number = UPTIME_WINDOW_MS,
  now: number = Date.now()
): Promise<Record<HealthComponent, UptimeResult>> {
  const cutoff = new Date(now - windowMs);
  const rows = await db.healthSample.findMany({
    where: { ts: { gte: cutoff } },
    select: { component: true, status: true, ts: true },
    orderBy: { ts: "asc" },
  });
  const out = {} as Record<HealthComponent, UptimeResult>;
  for (const c of HEALTH_COMPONENTS) {
    const cs = rows
      .filter((r) => r.component === c)
      .map((r) => ({ status: r.status as CompStatus, ts: r.ts }));
    out[c] = uptimeFromSamples(cs, now, windowMs);
  }
  return out;
}

/** Bucketed status history for one component (for the timeline strip). */
export async function componentTimeline(
  component: HealthComponent,
  windowMs: number = UPTIME_WINDOW_MS,
  bucketCount = 90,
  now: number = Date.now()
): Promise<TimelineBucket[]> {
  const cutoff = new Date(now - windowMs);
  const rows = await db.healthSample.findMany({
    where: { component, ts: { gte: cutoff } },
    select: { status: true, ts: true },
    orderBy: { ts: "asc" },
  });
  return bucketTimeline(
    rows.map((r) => ({ status: r.status as CompStatus, ts: r.ts })),
    now,
    windowMs,
    bucketCount
  );
}

/** Timelines for every component in one pass. */
export async function allTimelines(
  windowMs: number = UPTIME_WINDOW_MS,
  bucketCount = 90,
  now: number = Date.now()
): Promise<Record<HealthComponent, TimelineBucket[]>> {
  const cutoff = new Date(now - windowMs);
  const rows = await db.healthSample.findMany({
    where: { ts: { gte: cutoff } },
    select: { component: true, status: true, ts: true },
    orderBy: { ts: "asc" },
  });
  const out = {} as Record<HealthComponent, TimelineBucket[]>;
  for (const c of HEALTH_COMPONENTS) {
    const cs = rows
      .filter((r) => r.component === c)
      .map((r) => ({ status: r.status as CompStatus, ts: r.ts }));
    out[c] = bucketTimeline(cs, now, windowMs, bucketCount);
  }
  return out;
}

/** A serialisable, public-safe incident (title/body are curated copy, not raw detail). */
export type IncidentView = {
  id: string;
  component: HealthComponent | null;
  severity: IncidentSeverity;
  title: string;
  body: string;
  startedAt: string;
  resolvedAt: string | null;
  auto: boolean;
};

function toIncidentView(r: {
  id: string;
  component: string | null;
  severity: string;
  title: string;
  body: string;
  startedAt: Date;
  resolvedAt: Date | null;
  auto: boolean;
}): IncidentView {
  return {
    id: r.id,
    component: (r.component as HealthComponent | null) ?? null,
    severity: (r.severity as IncidentSeverity) ?? "degraded",
    title: r.title,
    body: r.body,
    startedAt: r.startedAt.toISOString(),
    resolvedAt: r.resolvedAt ? r.resolvedAt.toISOString() : null,
    auto: r.auto,
  };
}

/**
 * Open incidents + incidents resolved within the window. Safe for the PUBLIC
 * status page: only curated title/body/severity/timestamps are exposed, never a
 * probe's internal detail.
 */
export async function listIncidents(
  windowMs: number = UPTIME_WINDOW_MS,
  now: number = Date.now()
): Promise<{ open: IncidentView[]; resolved: IncidentView[] }> {
  const cutoff = new Date(now - windowMs);
  const [open, resolved] = await Promise.all([
    db.statusIncident.findMany({ where: { resolvedAt: null }, orderBy: { startedAt: "desc" } }),
    db.statusIncident.findMany({
      where: { resolvedAt: { not: null, gte: cutoff } },
      orderBy: { resolvedAt: "desc" },
      take: 50,
    }),
  ]);
  return { open: open.map(toIncidentView), resolved: resolved.map(toIncidentView) };
}

// ---- Job throughput (admin drill-down) ----------------------------------

export type JobStats = {
  windowMs: number;
  done: number;
  failed: number;
  /** Currently QUEUED (live depth, not windowed). */
  queued: number;
  /** Currently RUNNING (live). */
  running: number;
  /** failed / (done + failed) over the window, or `null` when nothing settled. */
  failureRate: number | null;
};

/** Queue depth + settled job outcomes over the window, straight from the Job table. */
export async function jobStats(
  windowMs = 24 * 60 * 60_000,
  now: number = Date.now()
): Promise<JobStats> {
  const since = new Date(now - windowMs);
  const [done, failed, queued, running] = await Promise.all([
    db.job.count({ where: { status: "DONE", updatedAt: { gte: since } } }),
    db.job.count({ where: { status: "FAILED", updatedAt: { gte: since } } }),
    db.job.count({ where: { status: "QUEUED" } }),
    db.job.count({ where: { status: "RUNNING" } }),
  ]);
  const settled = done + failed;
  return { windowMs, done, failed, queued, running, failureRate: settled === 0 ? null : failed / settled };
}

// Typed access layer over the key/value `Setting` store (db.setting).
//
// Plain (non-"use server") module so it can export the SETTINGS_DEFAULTS map,
// types and pure helpers alongside the async DB getters/setters. Import it from
// server components, server actions and the worker. Do NOT import from client
// components.
//
// Every admin-editable knob lives here with a default, so reads are total: a key
// that has never been written falls back to its SETTINGS_DEFAULTS value. Booleans
// are stored as the strings "true"/"false"; money is stored in cents; percents as
// plain numbers (e.g. "8.5" = 8.5%).

import { db } from "./db";
import { VPS_TERMS } from "./billing-terms";

export const SETTINGS_DEFAULTS = {
  // --- General / Branding ---
  //
  // Every default in this block is the string that was previously HARDCODED at the
  // render site it now feeds. That matters: `getSetting` falls back to these, so a
  // platform with an empty `Setting` table must render exactly what it rendered
  // before the wiring landed. A default of "" here would have blanked the footer
  // tagline and produced an empty `mailto:` on /contact the moment these keys were
  // read for the first time.
  brand_name: "Nxeon",
  // Verbatim the copy that used to be inline in components/marketing/MarketingFooter.tsx.
  // The footer is this key's only consumer, so the panel now previews what actually ships.
  brand_tagline:
    "Premium NVMe cloud VPS hosting, provisioned in seconds. Built for developers, teams, and everything you ship.",
  // Was "". The contact page advertises this address in three places and every one of
  // them hardcoded it, so the panel showed a blank support email while the marketing
  // site published a real one — and reading the blank key would have shipped
  // `mailto:` with no recipient.
  support_email: "support@nxeon.cloud",
  // DNS zone that managed-Nextcloud (NxCloud) instances live under:
  // <subdomain>.<nxcloud_zone>. A wildcard *.nxcloud_zone → the instance VMs (or a
  // per-instance A record) must resolve for auto-TLS to issue. See worker/nxcloud.ts.
  nxcloud_zone: "nxcloud.nxeon.cloud",
  // Blank is legitimate for these two: `renderInvoiceHTML` omits the seller block
  // entirely when they are unset rather than printing an empty "From" address.
  company_legal_name: "",
  company_address: "",
  social_twitter: "",
  social_github: "",
  social_discord: "",
  social_linkedin: "",
  footer_text: "",
  // Raw provider <script> body injected by components/marketing/LiveChat.tsx.
  livechat_snippet: "",
  // --- External review profiles (Reviews engine) ---
  //
  // Public URLs of our third-party review profiles. Managed on /admin/reviews.
  // They do two jobs: they turn the homepage review badges into real links (a
  // badge with no configured URL is not shown), and the post-purchase review-
  // request email only sends when at least one is set — so we never ask a
  // customer to "leave a review" with nowhere to send them. Blank = not set up.
  review_url_trustpilot: "",
  review_url_hostadvice: "",
  review_url_google: "",
  // Business-email DNS shown to customers (MX host + SPF include).
  //
  // These MUST match what mail actually runs on. They previously read
  // `mx.nxeon.email` / `_spf.nxeon.email` — a domain not used anywhere in this
  // platform — while `lib/actions-email-hosting.ts` hardcodes `mail.nxeon.cloud`
  // and `nxeon.cloud`, which is what real customer DNS uses and what an external
  // verifier confirmed working (revsports.ca: MX -> mail.nxeon.cloud,
  // SPF -> "v=spf1 include:nxeon.cloud ~all", DKIM/SPF/iprev all passing).
  //
  // Nothing read these keys, so the wrong values were harmless — but they were a
  // loaded trap: wiring the setting through without correcting it first would have
  // handed every business-email customer non-working DNS records and made the
  // deliverability checker fail correct setups. Corrected here so the wiring is
  // safe whenever someone does it.
  email_mx_host: "mail.nxeon.cloud",
  email_spf_include: "nxeon.cloud",

  // --- Billing ---
  currency: "USD",
  tax_percent: "0",
  min_topup_cents: "500",
  // Stored as a NUMBER OF MONTHS, and it must be one of `VPS_TERMS` (1/12/24/36).
  //
  // It used to be the enum "monthly" | "quarterly" | "annual", which nothing read —
  // and could not have been read: the platform sells no quarterly term at all, and
  // the enum had no way to express biennial or triennial. Wiring that vocabulary into
  // the deploy wizard would have meant an operator selecting "Quarterly", seeing
  // "Saved.", and the wizard silently pre-selecting monthly instead. Months are the
  // unit every charge path already speaks (`termMonths` on the order form,
  // `vpsTermPriceCents`, `addMonths`), so the setting now speaks it too and
