"use client";

import { useCallback, useEffect, useState } from "react";
import { AreaChart } from "@/components/ui/charts";

type Row = {
  time: number;
  cpu?: number | null;
  maxcpu?: number | null;
  memused?: number | null;
  memtotal?: number | null;
  netin?: number | null;
  netout?: number | null;
};

const TIMEFRAMES = [
  { tf: "hour", label: "1h" },
  { tf: "day", label: "24h" },
  { tf: "week", label: "7d" },
  { tf: "month", label: "30d" },
] as const;

function fmtTime(unixSec: number, tf: string): string {
  const d = new Date(unixSec * 1000);
  if (tf === "hour" || tf === "day") {
    return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
  }
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

function pickLabels(rows: Row[], tf: string, count = 6): string[] {
  if (rows.length === 0) return [];
  const labels: string[] = [];
  for (let i = 0; i < count; i++) {
    const idx = Math.round((i / (count - 1)) * (rows.length - 1));
    labels.push(fmtTime(rows[idx].time, tf));
  }
  return labels;
}

