"use server";

import { db } from "./db";
import { requireArea } from "./rbac";
import { revalidatePath } from "next/cache";

/**
 * Admin actions for the outbound-abuse queue. Fleet-area staff review alerts
 * raised by worker/abuse.ts and can acknowledge, resolve, or suspend the server.
 */

export async function acknowledgeAlert(id: string): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("fleet");
  await db.abuseAlert.update({ where: { id }, data: { status: "ACKNOWLEDGED" } });
  // Triaging an abuse case changes a customer's standing in the queue; record WHO
  // did it, the same way suspendForAbuse below does. Was unlogged.
  await db.auditLog.create({ data: { userId: admin.id, action: "abuse.acknowledge", detail: id } });
  revalidatePath("/admin/abuse");
  return { ok: true };
}

export async function resolveAlert(id: string): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("fleet");
  await db.abuseAlert.update({ where: { id }, data: { status: "RESOLVED", resolvedAt: new Date() } });
  // Closing an abuse case clears it from the queue — an attributable action.
  await db.auditLog.create({ data: { userId: admin.id, action: "abuse.resolve", detail: id } });
  revalidatePath("/admin/abuse");
  return { ok: true };
}

/** Suspend the server behind an alert (enqueues a SUSPEND job) and mark it ACTIONED. */
export async function suspendForAbuse(id: string): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("fleet");
  const alert = await db.abuseAlert.findUnique({ where: { id } });
  if (!alert) return { error: "Alert not found." };
  const server = await db.server.findUnique({ where: { id: alert.serverId } });
  if (!server) return { error: "Server no longer exists." };
  if (server.status !== "SUSPENDED") {
    // Record WHY before enqueuing. Without it the billing engine cannot tell an
    // abuse suspension from an unpaid one, and two things go wrong: the overdue
    // sweep eventually DELETES the server as a non-payer (the renewal sweep skips
    // suspended servers, so it was never billed or warned in the meantime), and
    // the customer can lift the suspension themselves by clicking "Renew now".
    await db.server.update({
      where: { id: server.id },
      data: {
        suspendReason: "ABUSE",
        suspendedNote: "suspended pending an abuse review — contact support",
      },
    });
    await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
  }
  await db.abuseAlert.update({ where: { id }, data: { status: "ACTIONED" } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "abuse.suspend", detail: `${server.hostname} (${alert.kind}) — ${alert.detail}` },
  });
  revalidatePath("/admin/abuse");
  return { ok: true };
}
