export async function adminListHostingInfra(): Promise<{
  plans: { id: string; slug: string; name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; active: boolean }[];
  nodes: { id: string; name: string; publicIp: string; status: string; enabled: boolean; used: number; maxAccounts: number; hardenStatus: string; hardenedAt: string | null; hardenLog: string | null }[];
}> {
  await requireArea("fleet");
  const [plans, nodes] = await Promise.all([
    db.hostingPlan.findMany({ orderBy: { sortOrder: "asc" } }),
    db.hostingNode.findMany({ orderBy: { name: "asc" } }),
  ]);
  const nodeViews = await Promise.all(
    nodes.map(async (n) => ({
      id: n.id, name: n.name, publicIp: n.publicIp, status: n.status, enabled: n.enabled,
      maxAccounts: n.maxAccounts,
      hardenStatus: n.hardenStatus, hardenedAt: n.hardenedAt?.toISOString() ?? null, hardenLog: n.hardenLog,
      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
    })),
  );
  return {
    plans: plans.map((p) => ({ id: p.id, slug: p.slug, name: p.name, priceCents: p.priceCents, diskGB: p.diskGB, maxSites: p.maxSites, maxDatabases: p.maxDatabases, bandwidthTB: p.bandwidthTB, active: p.active })),
    nodes: nodeViews,
  };
}

export async function adminCreateHostingPlan(_prev: unknown, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("fleet");
  const slug = String(formData.get("slug") ?? "").trim().toLowerCase();
  const name = String(formData.get("name") ?? "").trim();
  const priceCents = Math.round(Number(formData.get("priceCents") ?? 0));
  const diskGB = Math.round(Number(formData.get("diskGB") ?? 0));
  const maxSites = Math.round(Number(formData.get("maxSites") ?? 1));
  const maxDatabases = Math.round(Number(formData.get("maxDatabases") ?? 1));
  if (!/^[a-z][a-z0-9-]{1,31}$/.test(slug)) return { error: "Slug: lowercase letters, digits, dashes." };
  if (!name) return { error: "Enter a plan name." };
  if (priceCents < 0 || diskGB < 1) return { error: "Price and disk must be positive." };
  if (await db.hostingPlan.findUnique({ where: { slug } })) return { error: "A plan with that slug exists." };
  await db.hostingPlan.create({ data: { slug, name, priceCents, diskGB, maxSites, maxDatabases } });
  revalidatePath("/admin/hosting");
  return { ok: true };
}

export async function adminToggleHostingPlan(id: string): Promise<void> {
  await requireArea("fleet");
  const p = await db.hostingPlan.findUnique({ where: { id } });
  if (p) await db.hostingPlan.update({ where: { id }, data: { active: !p.active } });
  revalidatePath("/admin/hosting");
}

