  const allIncidents: AdminIncident[] = [...incidents.open, ...incidents.resolved];
  const failurePct = jobs24h.failureRate === null ? null : jobs24h.failureRate * 100;

  const newestBackupAgeMs = backups.newestCtime ? Date.now() - backups.newestCtime * 1000 : null;
  const oldestBackupAgeMs = backups.oldestCtime ? Date.now() - backups.oldestCtime * 1000 : null;
  const backupsStale = newestBackupAgeMs !== null && newestBackupAgeMs > BACKUP_STALE_MS;

  return (
    <div className="space-y-6">
