            <p className="text-[13px] text-slate-400">Worker</p>
            <Badge tone={HEALTH_TONE[wh.status]}>{wh.status}</Badge>
          </div>
          <p className="mt-2 text-sm text-slate-300">{wh.detail}</p>
          <p className="mt-1 text-xs text-slate-500">
            {wh.queuedBacklog} queued · {wh.stuckRunning} stuck
          </p>
        </div>
        <div className="card p-5">
          <div className="flex items-center justify-between">
            <p className="text-[13px] text-slate-400">Stuck jobs</p>
            <Badge tone={stuck.length > 0 ? "red" : "green"}>{stuck.length}</Badge>
          </div>
          <p className="mt-2 text-sm text-slate-300">
            {stuck.length === 0 ? "No jobs stuck in RUNNING." : "Jobs exceeding the stuck threshold."}
          </p>
        </div>
        <div className="card p-5">
          <div className="flex items-center justify-between">
            <p className="text-[13px] text-slate-400">Newest backup</p>
            <Badge tone={backups.reachable ? (backupsStale ? "amber" : "green") : "slate"}>
              {backups.reachable ? (newestBackupAgeMs !== null ? fmtAge(newestBackupAgeMs) : "none") : "n/a"}
            </Badge>
          </div>
          <p className="mt-2 text-sm text-slate-300">
            {backups.reachable ? `${backups.count} backup(s) on disk` : "Backup storage not listable."}
          </p>
        </div>
        <div className="card p-5">
          <div className="flex items-center justify-between">
            <p className="text-[13px] text-slate-400">Oldest backup</p>
            <Badge tone="slate">
              {backups.reachable && oldestBackupAgeMs !== null ? fmtAge(oldestBackupAgeMs) : "—"}
            </Badge>
          </div>
          <p className="mt-2 text-sm text-slate-300">Age of the oldest retained backup.</p>
        </div>
      </div>

      {/* Job throughput (last 24h) — live queue depth + settled outcomes */}
      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <div className="card p-5">
          <p className="text-[13px] text-slate-400">Queue depth</p>
          <p className="mt-1 text-2xl font-semibold text-white">{jobs24h.queued}</p>
          <p className="mt-1 text-xs text-slate-500">{jobs24h.running} running now</p>
        </div>
        <div className="card p-5">
          <div className="flex items-center justify-between">
            <p className="text-[13px] text-slate-400">Failure rate (24h)</p>
            <Badge tone={failurePct === null ? "slate" : failurePct > 20 ? "red" : failurePct > 5 ? "amber" : "green"}>
              {failurePct === null ? "no jobs" : `${failurePct.toFixed(0)}%`}
            </Badge>
          </div>
          <p className="mt-2 text-sm text-slate-300">
            {jobs24h.failed} failed / {jobs24h.done + jobs24h.failed} settled
          </p>
        </div>
        <div className="card p-5">
          <p className="text-[13px] text-slate-400">Completed (24h)</p>
          <p className="mt-1 text-2xl font-semibold text-white">{jobs24h.done}</p>
          <p className="mt-1 text-xs text-slate-500">Jobs finished in the last day.</p>
        </div>
        <div className="card p-5">
          <p className="text-[13px] text-slate-400">Failed (24h)</p>
          <p className="mt-1 text-2xl font-semibold text-white">{jobs24h.failed}</p>
          <p className="mt-1 text-xs text-slate-500">Jobs that ended in FAILED.</p>
        </div>
      </div>

      {/* Per-subsystem uptime from real HealthSample history */}
      <div className="card p-5">
        <div className="flex items-baseline justify-between">
          <h2 className="font-semibold">Subsystem uptime</h2>
          <span className="text-xs text-slate-500">Last {UPTIME_DAYS} days · from health snapshots</span>
        </div>
        <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          {(HEALTH_COMPONENTS as readonly HealthComponent[]).map((c) => {
            const u = uptime[c];
            return (
              <div key={c} className="rounded-lg border border-white/[0.06] p-4">
                <div className="flex items-center justify-between">
                  <p className="text-sm font-medium text-white">{COMPONENT_LABELS[c]}</p>
                  <Badge tone={uptimeTone(u.pct)}>{pctText(u.pct)}</Badge>
                </div>
                <p className="mt-2 text-xs text-slate-500">
                  {u.total === 0
                    ? "Collecting data — no snapshots yet."
                    : `${u.total} samples · ${u.degraded} degraded · ${u.down} down`}
                </p>
              </div>
            );
          })}
        </div>
      </div>

      {/* Incident management — post/resolve manual StatusIncidents */}
      <IncidentManager incidents={allIncidents} />

      {/* Node capacity: RAM + disk */}
      <div className="card p-5">
        <h2 className="font-semibold">Node capacity</h2>
        <p className="mt-1 text-xs text-slate-500">
          Live memory and storage usage per node (read-only from Proxmox). Bars turn amber past{" "}
          {Math.round(RAM_WARN_RATIO * 100)}% RAM / {Math.round(DISK_WARN_RATIO * 100)}% disk.
        </p>

        <div className="mt-4 space-y-5">
          {ram.map((r) => {
            const nodeStorage = storage.filter((s) => s.node === r.node);
            return (
              <div key={r.node} className="rounded-lg border border-white/[0.06] p-4">
                <div className="flex items-center justify-between">
                  <p className="font-medium">{r.node}</p>
                  {!r.reachable && <Badge tone="red">unreachable</Badge>}
                </div>

                {r.reachable && (
                  <div className="mt-3">
                    <div className="flex items-center justify-between text-xs text-slate-400">
                      <span>Memory</span>
                      <span>
                        {fmtBytes(r.used)} / {fmtBytes(r.total)} · {Math.round(r.ratio * 100)}%
                        {" · "}CPU {Math.round(r.cpu * 100)}%
                      </span>
                    </div>
                    <MeterBar value={r.used} max={r.total || 1} color={meterColor(r.ratio, RAM_WARN_RATIO)} className="mt-1.5" />
                  </div>
                )}

                {nodeStorage.map((s) => (
                  <div key={s.storage} className="mt-3">
                    <div className="flex items-center justify-between text-xs text-slate-400">
                      <span>
                        Disk · <span className="font-mono">{s.storage}</span>
                      </span>
                      <span>
                        {s.reachable ? (
                          <>
                            {fmtBytes(s.used)} / {fmtBytes(s.total)} · {Math.round(s.ratio * 100)}%
                          </>
                        ) : (
                          "unavailable"
                        )}
                      </span>
                    </div>
                    {s.reachable && (
                      <MeterBar value={s.used} max={s.total || 1} color={meterColor(s.ratio, DISK_WARN_RATIO)} className="mt-1.5" />
                    )}
                  </div>
                ))}
              </div>
            );
          })}
          {ram.length === 0 && <p className="text-sm text-slate-500">No nodes configured.</p>}
        </div>
      </div>

      {/* Stuck jobs detail */}
      {stuck.length > 0 && (
        <div className="card p-0">
          <div className="px-5 pt-5">
            <h2 className="font-semibold">Stuck jobs</h2>
            <p className="mt-1 text-xs text-slate-500">Jobs in RUNNING past the stuck threshold — may need manual intervention.</p>
          </div>
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Type</th>
                  <th>Server</th>
                  <th>Attempts</th>
                  <th className="text-right">Running for</th>
                </tr>
              </thead>
              <tbody>
                {stuck.map((j) => (
                  <tr key={j.id}>
                    <td className="text-xs font-medium">{j.type}</td>
                    <td className="text-xs">
                      {j.serverId ? (
                        <Link href={`/admin/servers/${j.serverId}`} className="hover:text-brand-300">
                          {j.hostname ?? j.serverId}
                        </Link>
                      ) : (
                        "—"
                      )}
                    </td>
                    <td className="text-xs text-slate-400">{j.attempts}</td>
                    <td className="text-right text-xs text-amber-400">{timeAgo(j.updatedAt)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <NodeMetrics />

      <div className="card p-0">
        <div className="px-5 pt-5">
          <h2 className="font-semibold">Virtual machines</h2>
          <p className="mt-1 text-xs text-slate-500">
            Live from the Proxmox API (templates excluded). VMs without a platform server record are flagged
            unmanaged.
          </p>
        </div>
        {!pveOk ? (
          <p className="px-5 py-8 text-sm text-slate-500">
            Could not reach the Proxmox API — the VM list will reappear once the hypervisor responds.
          </p>
        ) : vms.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">No virtual machines on the node.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>VMID</th>
                  <th>Name</th>
                  <th>Owner</th>
                  <th>Status</th>
                  <th>CPU</th>
                  <th className="min-w-40">Memory</th>
                  <th>Disk</th>
                  <th className="text-right">Uptime</th>
                </tr>
              </thead>
              <tbody>
                {vms.map((v) => {
                  const rec = byVmid.get(v.vmid);
                  const orphan = !rec && v.vmid < 9000;
                  const uptimeH = v.uptime ? Math.floor(v.uptime / 3600) : 0;
                  return (
                    <tr key={v.vmid}>
                      <td className="font-mono text-xs">{v.vmid}</td>
                      <td>
                        {rec ? (
                          <Link href={`/admin/servers/${rec.id}`} className="font-medium hover:text-brand-300">
                            {rec.hostname}
                          </Link>
                        ) : (
                          <span className="font-medium">{v.name ?? "—"}</span>
                        )}
                        {orphan && (
                          <span className="ml-2">
                            <Badge tone="amber">unmanaged</Badge>
                          </span>
                        )}
                      </td>
                      <td className="text-xs text-slate-400">{rec?.user.email ?? "—"}</td>
                      <td>
                        <StatusDot status={v.status === "running" ? "online" : "STOPPED"} label={v.status} />
                      </td>
                      <td className="text-xs">
                        {v.status === "running" ? `${((v.cpu ?? 0) * 100).toFixed(1)}% / ${v.cpus} vCPU` : "—"}
                      </td>
                      <td>
                        {v.status === "running" ? (
                          <div>
                            <MeterBar value={v.mem ?? 0} max={v.maxmem ?? 1} color="#3b82f6" />
                            <p className="mt-1 text-[11px] text-slate-500">
                              {fmtBytes(v.mem ?? 0)} / {fmtBytes(v.maxmem ?? 0)}
                            </p>
                          </div>
                        ) : (
                          <span className="text-xs text-slate-600">{fmtBytes(v.maxmem ?? 0)} allocated</span>
                        )}
                      </td>
                      <td className="text-xs">{fmtBytes(v.maxdisk ?? 0)}</td>
                      <td className="text-right text-xs text-slate-400">
                        {v.status === "running" && v.uptime
                          ? uptimeH >= 24
                            ? `${Math.floor(uptimeH / 24)}d ${uptimeH % 24}h`
                            : `${uptimeH}h`
                          : "—"}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

