/// A capacity warning for a single node DIMENSION (CPU/RAM/DISK/ACCOUNTS),
/// raised by the node-capacity sweep (worker/monitor.ts → nodeCapacitySweep, math
/// in lib/node-capacity.ts). One OPEN row per (nodeKind, nodeId, dimension): the
/// sweep reconciles against it so a persistent condition alerts on STATE CHANGE
/// (new / WARN⇄CRITICAL escalation) and at most once per cooldown, never every
/// sweep — the same debounce discipline AbuseAlert uses. `pct` is the latest
/// utilization that tripped it; the row auto-RESOLVES (with hysteresis) when the
/// node drops back under the warn threshold, or when the node itself is deleted.
///
/// Deliberately NOT stored in the `Setting` KV: that map is shipped wholesale to
/// the admin settings page (see lib/settings.ts), so a blob of per-node alert
/// state would leak to the browser and grow unbounded. A dedicated table matches
/// AbuseAlert and keeps the admin panels' queries cheap and indexed.
model NodeAlert {
  id             String    @id @default(cuid())
  nodeKind       String // PROXMOX | HOSTING
  nodeId         String // Node.id or HostingNode.id (no FK — survives node delete for the resolve trail)
  nodeName       String
  dimension      String // CPU | RAM | DISK | ACCOUNTS
  severity       String    @default("WARN") // WARN | CRITICAL
  pct            Int       @default(0) // latest utilization percent that tripped/holds this alert
  detail         String
  metric         Json? // measured values (e.g. { allocPct, realPct, warnPct, critPct })
  status         String    @default("OPEN") // OPEN | RESOLVED
  lastNotifiedAt DateTime? // gates the per-cooldown re-alert on a persistent condition
  createdAt      DateTime  @default(now())
  updatedAt      DateTime  @updatedAt
  resolvedAt     DateTime?

  @@unique([nodeKind, nodeId, dimension, status])
  @@index([status, createdAt])
  @@index([nodeKind, nodeId])
}

// ============================================================================
// Control panel (cPanel/Plesk-style VPS management over SSH)

  resolvedAt     DateTime?

  // No DB unique on (nodeKind,nodeId,dimension): a partial "one OPEN row" index
  // isn't portably expressible in Prisma, and a full unique would collide the
  // moment a second RESOLVED row is written for a dimension that recovered twice.
  // The sweep enforces the single-OPEN invariant in code (findFirst OPEN), the
  // same way AbuseAlert does.
  @@index([status, createdAt])
  @@index([nodeKind, nodeId])
}

