/**
 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
 * a node this order would push to/past the CRITICAL capacity threshold when
 * another node has room. Falls back to primary (any node) when every candidate is
 * already critical — the scheduler never REFUSES an order for a capacity warning
 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
 * roomier node when one exists. DB-only so order placement never blocks on a
 * Proxmox round trip.
 */
async function scheduleNode(planRamMB: number) {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } } },
      });
      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
      // Commitment AFTER this VM lands — that's what decides whether placing here
      // tips the node critical.
      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
      return { node: n, free: n.capacityRamMB - used, projectedPct };
    }),
  );
  const { critPct } = await nodeThresholds();
  const roomy = loads.filter((l) => l.projectedPct < critPct);
  const pool = roomy.length > 0 ? roomy : loads;
  pool.sort((a, b) => b.free - a.free);
  return pool[0].node;
}

