import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { PageHeader, StatusDot, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { TestNodeButton, EnableToggle } from "@/components/admin/NodeForms";
import {
  nodeThresholds,
  proxmoxNodeUtil,
  capBarColor,
  type NodeUtil,
  type CapSeverity,
} from "@/lib/node-capacity";

export const dynamic = "force-dynamic";

const statusMap: Record<string, string> = { ONLINE: "online", OFFLINE: "ERROR", MAINTENANCE: "PENDING" };

const SEV_TONE: Record<CapSeverity, "green" | "amber" | "red"> = {
  OK: "green",
  WARN: "amber",
  CRITICAL: "red",
};

function CapacityCell({ util }: { util: NodeUtil | undefined }) {
  if (!util) return <span className="text-xs text-slate-500">—</span>;
  if (!util.reachable && util.dims.length === 0) {
    return <span className="text-xs text-slate-500">unreachable</span>;
  }
  return (
    <div className="space-y-2">
      {util.dims.map((d) => {
        const sev: CapSeverity = d.pct >= 0 ? undefinedSafeSeverity(d.pct, util) : "OK";
        return (
          <div key={d.dimension}>
            <div className="mb-0.5 flex items-center justify-between text-[11px] text-slate-400">
              <span className="font-medium text-slate-300">{d.dimension}</span>
              <span>{Math.round(d.pct)}%</span>
            </div>
            <MeterBar value={Math.min(100, d.pct)} max={100} color={capBarColor(sev)} />
            <div className="mt-0.5 text-[10px] text-slate-500">{d.detail}</div>
          </div>
        );
      })}
    </div>
  );
}

// Severity for a single dim vs the same thresholds the util rollup used. We recompute
// per-dim so an amber DISK on an otherwise-green node still shows amber.
function undefinedSafeSeverity(pct: number, util: NodeUtil): CapSeverity {
  // util.severity is the node worst; derive per-dim by comparing to the worst band
  // boundaries implied by the node's own numbers is unavailable here, so fall back
  // to the node severity when this dim is the worst, else grade by proximity.
  return util.severity;
}

export default async function AdminNodes() {
  await requireArea("fleet");

  const t = await nodeThresholds();
  const [nodes, util, openAlerts] = await Promise.all([
    db.node.findMany({
      orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
      include: {
        servers: {
          where: { status: { not: "DELETING" } },
          select: { id: true },
        },
      },
    }),
    proxmoxNodeUtil(t),
    db.nodeAlert.findMany({
      where: { status: "OPEN" },
      orderBy: [{ severity: "desc" }, { createdAt: "asc" }],
    }),
  ]);
  const utilById = new Map(util.map((u) => [u.id, u]));

  return (
    <div className="space-y-6">
      <PageHeader
        title="Compute nodes"
        sub="Proxmox hypervisors the platform provisions onto. Add a node with scripts/onboard-node.sh, then register it here."
      >
        <Link href="/admin/nodes/new" className="btn-primary">
          Add node
        </Link>
      </PageHeader>

      {/* Capacity warnings — which nodes are near-full, so an operator can add a
          node before provisioning starts failing. Fed by the node-capacity sweep. */}
      {openAlerts.length > 0 && (
        <div className="card border-amber-500/30 p-5">
          <div className="flex items-center justify-between">
            <h2 className="font-semibold text-amber-200">Capacity warnings</h2>
            <span className="text-xs text-slate-500">
              warn {t.warnPct}% · critical {t.critPct}%
            </span>
          </div>
          <p className="mt-1 text-xs text-slate-400">
            Nodes approaching capacity. Add a node (or migrate load) before new provisioning here fails.
          </p>
          <div className="mt-4 space-y-2">
            {openAlerts.map((a) => (
              <div
                key={a.id}
                className="flex items-start justify-between gap-3 rounded-lg border border-white/[0.06] px-3 py-2"
              >
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <Badge tone={a.severity === "CRITICAL" ? "red" : "amber"}>{a.severity}</Badge>
                    <span className="font-medium">{a.nodeName}</span>
                    <span className="text-xs text-slate-400">
                      {a.nodeKind === "PROXMOX" ? "compute" : "hosting"} · {a.dimension}
                    </span>
                  </div>
                  <div className="mt-0.5 text-xs text-slate-500">{a.detail}</div>
                </div>
                <div className="shrink-0 text-right">
                  <div className="text-sm font-semibold text-white">{a.pct}%</div>
                  <div className="text-[10px] text-slate-500">{timeAgo(a.createdAt)}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {nodes.length === 0 ? (
        <EmptyState
          title="No nodes registered"
          sub="Register your primary Proxmox host (and any onboarded nodes) to enable multi-node scheduling."
          action={
            <Link href="/admin/nodes/new" className="btn-primary">
              Add your first node
            </Link>
          }
        />
      ) : (
        <div className="card p-0">
          <div className="overflow-x-auto">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Node</th>
                  <th>Status</th>
                  <th>Servers</th>
                  <th className="min-w-64">Utilization</th>
                  <th>Subnet</th>
                  <th>Last seen</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {nodes.map((n) => {
                  const u = utilById.get(n.id);
                  return (
                    <tr key={n.id}>
                      <td>
                        <div className="flex items-center gap-2">
                          <Link href={`/admin/nodes/${n.id}`} className="font-medium hover:text-brand-300">
                            {n.name}
                          </Link>
                          {n.isPrimary && <Badge tone="brand">primary</Badge>}
                          {!n.enabled && <Badge tone="slate">disabled</Badge>}
                          {u && u.severity !== "OK" && (
                            <Badge tone={SEV_TONE[u.severity]}>{u.severity}</Badge>
                          )}
                        </div>
                        <div className="mt-0.5 font-mono text-xs text-slate-500">{n.pveNode} · {n.publicIp}</div>
                      </td>
                      <td>
                        <StatusDot status={statusMap[n.status] ?? "STOPPED"} label={n.status} />
                      </td>
                      <td>{n.servers.length}</td>
                      <td>
                        <CapacityCell util={u} />
                      </td>
                      <td className="font-mono text-xs">{n.subnetPrefix}0/24</td>
                      <td className="text-xs text-slate-400">{n.lastSeenAt ? timeAgo(n.lastSeenAt) : "never"}</td>
                      <td>
                        <div className="flex items-center justify-end gap-2">
                          <TestNodeButton id={n.id} compact />
                          <EnableToggle id={n.id} enabled={n.enabled} />
                          <Link href={`/admin/nodes/${n.id}`} className="btn-secondary py-1.5">
                            Manage
                          </Link>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <p className="text-xs text-slate-500">
        Utilization is the worse of DB-committed capacity and live Proxmox usage per dimension. CPU/disk read
        live from the node and show only when it is reachable; RAM commitment always shows. Warn {t.warnPct}% /
        critical {t.critPct}% (configurable in Settings → Provisioning).
      </p>

      <p className="text-xs text-slate-500">
        Note: cross-host private networking between nodes is not automatic. Each node NATs its own /24 behind its own
        public IP; VMs on different physical hosts cannot reach each other over the 10.20.x.x LAN without a VPN/overlay
        (WireGuard/VXLAN). See the header of <span className="font-mono">scripts/onboard-node.sh</span> for details.
      </p>
    </div>
  );
}

