type Plan = { id: string; slug: string; name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; active: boolean };
type CapSev = "OK" | "WARN" | "CRITICAL";
type NodeUtil = {
  severity: CapSev;
  warnPct: number;
  critPct: number;
  dims: { dimension: string; pct: number; sev: CapSev; detail: string }[];
};
type Node = {
  id: string; name: string; publicIp: string; status: string; enabled: boolean; used: number; maxAccounts: number;
  hardenStatus: string; hardenedAt: string | null; hardenLog: string | null;
  util: NodeUtil;
};

const SEV_BAR: Record<CapSev, string> = { OK: "#34d399", WARN: "#f59e0b", CRITICAL: "#ef4444" };
const SEV_TEXT: Record<CapSev, string> = { OK: "text-emerald-300", WARN: "text-amber-300", CRITICAL: "text-red-400" };

/** Compact per-dimension utilization meters for one hosting node. */
function NodeUtilCell({ util }: { util: NodeUtil }) {
  if (!util.dims.length) return <span className="text-xs text-slate-500">—</span>;
  return (
    <div className="min-w-[180px] space-y-1.5">
      {util.dims.map((d) => (
        <div key={d.dimension} title={d.detail}>
          <div className="flex items-center justify-between text-[11px] text-slate-400">
            <span className="font-medium text-slate-300">{d.dimension}</span>
            <span className={SEV_TEXT[d.sev]}>{d.pct}%</span>
          </div>
          <div className="mt-0.5 h-1.5 w-full rounded-full bg-white/[0.06]">
            <div
              className="h-1.5 rounded-full transition-all"
              style={{ width: `${Math.min(100, d.pct)}%`, background: SEV_BAR[d.sev] }}
            />
          </div>
        </div>
      ))}
    </div>
  );
}

{/* Capacity warnings — which hosting nodes are near-full, so an operator
    can add a node before account provisioning starts failing. */}
{nodes.some((n) => n.util.severity !== "OK") && (
  <div className="rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2.5">
    <p className="text-xs font-medium text-amber-200">Capacity warnings</p>
    <ul className="mt-1 space-y-0.5">
      {nodes
        .filter((n) => n.util.severity !== "OK")
        .map((n) => {
          const worst = n.util.dims.filter((d) => d.sev !== "OK");
          return (
            <li key={n.id} className="text-xs text-slate-300">
              <span className={SEV_TEXT[n.util.severity]}>[{n.util.severity}]</span>{" "}
              <span className="font-medium">{n.name}</span> —{" "}
              {worst.map((d) => `${d.dimension} ${d.pct}%`).join(", ")}
            </li>
          );
        })}
    </ul>
  </div>
)}
{nodes.length > 0 && (
  <div className="overflow-x-auto">
    <table className="w-full text-sm">
      <thead className="text-left text-xs text-slate-500"><tr><th className="py-1">Node</th><th>Public IP</th><th>Accounts</th><th className="min-w-[190px]">Utilization</th><th>Status</th><th>Hardening</th><th></th></tr></thead>
      <tbody>
        {nodes.map((n) => (
          <tr key={n.id} className="border-t border-white/5 align-top">
            <td className="py-1.5">
              <div className="flex items-center gap-2">
                <span>{n.name}</span>
                {n.util.severity !== "OK" && (
                  <span className={`text-[10px] font-semibold uppercase ${SEV_TEXT[n.util.severity]}`}>
                    {n.util.severity}
                  </span>
                )}
              </div>
            </td>
            <td className="font-mono text-xs">{n.publicIp}</td>
            <td>{n.used}/{n.maxAccounts}</td>
            <td className="py-1.5"><NodeUtilCell util={n.util} /></td>
            <td>{n.enabled ? <span className="text-emerald-300">{n.status.toLowerCase()}</span> : <span className="text-slate-500">disabled</span>}</td>
            <td className="py-1.5"><HardenCell node={n} /></td>
            <td className="text-right"><form action={adminToggleHostingNode.bind(null, n.id)}><button className="text-xs text-brand-300 hover:underline">{n.enabled ? "Disable" : "Enable"}</button></form></td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
)}

